result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/expectations.py", "content": """"A tiny, API-first validation suite framework (mini Great Expectations).

Usage:
    suite = Suite()
    suite.expect_column_values_not_null("age")
    suite.expect_column_values_between("age", 0, 120)
    result = suite.run(rows)   # rows: list[dict]

run() never raises on data problems -- it reports them. It only raises
on misuse (e.g. an unknown column name -> KeyError).
"""

from __future__ import annotations

import re
from typing import Any, Iterable, Optional

MAX_EXAMPLES = 5


def _is_missing(value: Any) -> bool:
    """Treat None and empty string as missing values."""
    return value is None or (isinstance(value, str) and value == "")


class _Expectation:
    """Base class: subclasses implement check()."""

    def check(self, rows: list[dict]) -> dict:
        raise NotImplementedError

    # Helpers shared by subclasses -------------------------------------------------

    @staticmethod
    def _values(rows: list[dict], column: str) -> list[Any]:
        return [row.get(column) for row in rows]

    def _result(self, success: bool, observed: dict) -> dict:
        payload = {"success": bool(success)}
        payload.update(observed)
        return payload

    def _examples(self, bad_rows: Iterable[tuple[int, Any]], column: str) -> list[dict]:
        return [
            {"index": idx, "value": value}
            for idx, value in list(bad_rows)[:MAX_EXAMPLES]
        ]


class ExpectColumnValuesNotNull(_Expectation):
    def __init__(self, column: str):
        self.column = column

    def check(self, rows: list[dict]) -> dict:
        values = self._values(rows, self.column)
        null_count = sum(1 for v in values if _is_missing(v))
        examples = self._examples(
            ((i, v) for i, v in enumerate(values) if _is_missing(v)), self.column
        )
        return self._result(
            null_count == 0,
            {
                "expectation": "expect_column_values_not_null",
                "column": self.column,
                "null_count": null_count,
                "row_count": len(rows),
                "null_examples": examples,
            },
        )


class ExpectColumnValuesBetween(_Expectation):
    def __init__(self, column: str, lo: float, hi: float):
        self.column = column
        self.lo = lo
        self.hi = hi

    def check(self, rows: list[dict]) -> dict:
        values = self._values(rows, self.column)

        def out_of_range(v: Any) -> bool:
            if _is_missing(v):
                return False  # nulls are not range violations; use not_null for that
            try:
                num = float(v)
            except (TypeError, ValueError):
                return True
            return not (self.lo <= num <= self.hi)

        offenders = [(i, v) for i, v in enumerate(values) if out_of_range(v)]
        return self._result(
            len(offenders) == 0,
            {
                "expectation": "expect_column_values_between",
                "column": self.column,
                "min": self.lo,
                "max": self.hi,
                "out_of_range_count": len(offenders),
                "out_of_range_examples": [
                    {"index": i, "value": v} for i, v in offenders[:MAX_EXAMPLES]
                ],
            },
        )


class ExpectColumnUnique(_Expectation):
    def __init__(self, column: str):
        self.column = column

    def check(self, rows: list[dict]) -> dict:
        seen: set = set()
        duplicate_values: list[tuple[int, Any]] = []
        for i, v in enumerate(self._values(rows, self.column)):
            key = ("__null__",) if _is_missing(v) else (type(v).__name__, v)
            if key in seen:
                duplicate_values.append((i, v))
            else:
                seen.add(key)
        distinct = {v for v in self._values(rows, self.column)}
        return self._result(
            len(duplicate_values) == 0,
            {
                "expectation": "expect_column_unique",
                "column": self.column,
                "duplicate_count": len(duplicate_values),
                "distinct_count": len(distinct),
                "duplicate_examples": self._examples(duplicate_values, self.column),
            },
        )


class ExpectTableRowCountBetween(_Expectation):
    def __init__(self, lo: int, hi: int):
        self.lo = lo
        self.hi = hi

    def check(self, rows: list[dict]) -> dict:
        count = len(rows)
        return self._result(
            self.lo <= count <= self.hi,
            {
                "expectation": "expect_table_row_count_between",
                "min": self.lo,
                "max": self.hi,
                "observed_row_count": count,
            },
        )


class ExpectColumnMatchesRegex(_Expectation):
    def __init__(self, column: str, pattern: str):
        self.column = column
        self.pattern = pattern
        self._compiled = re.compile(pattern)

    def check(self, rows: list[dict]) -> dict:
        def mismatch(v: Any) -> bool:
            if _is_missing(v):
                return False  # nulls handled by expect_column_values_not_null
            return self._compiled.search(str(v)) is None

        offenders = [
            (i, v)
            for i, v in enumerate(self._values(rows, self.column))
            if mismatch(v)
        ]
        return self._result(
            len(offenders) == 0,
            {
                "expectation": "expect_column_matches_regex",
                "column": self.column,
                "regex": self.pattern,
                "unexpected_count": len(offenders),
                "unexpected_examples": self._examples(offenders, self.column),
            },
        )


class Suite:
    """An ordered collection of expectations."""

    def __init__(self, name: str = "default"):
        self.name = name
        self._expectations: list[_Expectation] = []

    # Builder API ------------------------------------------------------------------

    def expect_column_values_not_null(self, column: str) -> "Suite":
        self._expectations.append(ExpectColumnValuesNotNull(column))
        return self

    def expect_column_values_between(
        self, column: str, lo: float, hi: float
    ) -> "Suite":
        self._expectations.append(ExpectColumnValuesBetween(column, lo, hi))
        return self

    def expect_column_unique(self, column: str) -> "Suite":
        self._expectations.append(ExpectColumnUnique(column))
        return self

    def expect_table_row_count_between(self, lo: int, hi: int) -> "Suite":
        self._expectations.append(ExpectTableRowCountBetween(lo, hi))
        return self

    def expect_column_matches_regex(self, column: str, pattern: str) -> "Suite":
        self._expectations.append(ExpectColumnMatchesRegex(column, pattern))
        return self

    # Execution --------------------------------------------------------------------

    def run(self, rows: list[dict]) -> dict:
        """Run all expectations. Never raises on data problems.

        Raises KeyError if any expectation references a column absent
        from the data.
        """
        if rows:
            columns = set(rows[0].keys())
            for exp in self._expectations:
                column = getattr(exp, "column", None)
                if column is not None and column not in columns:
                    raise KeyError(column)
        else:
            # Empty dataset: any column expectation is unusable.
            for exp in self._expectations:
                if getattr(exp, "column", None) is not None:
                    raise KeyError(exp.column)

        results = [exp.check(rows) for exp in self._expectations]
        return {
            "suite": self.name,
            "success": all(r["success"] for r in results),
            "results": results,
        }
"})
